import{_ as e,o as i,c as o,a2 as a}from"./chunks/framework.BXzK3EA4.js";const h=JSON.parse('{"title":"Unity 아키텍처 구현 계획","description":"","frontmatter":{},"headers":[],"relativePath":"rules/Unity-Architecture-Implementation-Plan.md","filePath":"rules/Unity-Architecture-Implementation-Plan.md"}'),d={name:"rules/Unity-Architecture-Implementation-Plan.md"};function n(r,t,l,c,s,p){return i(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="unity-아키텍처-구현-계획" tabindex="-1">Unity 아키텍처 구현 계획 <a class="header-anchor" href="#unity-아키텍처-구현-계획" aria-label="Permalink to &quot;Unity 아키텍처 구현 계획&quot;">​</a></h1><p>이 계획은 <a href="/rules/Unity-System-Design.html">Unity 시스템 설계 계약</a>을 코드로 옮기는 순서와 각 단계의 중단 조건을 정의합니다. 설계 계약과 계획이 Wiki에 먼저 합쳐지기 전에는 제품 코드를 변경하지 않습니다.</p><h2 id="계약-요약" tabindex="-1">계약 요약 <a class="header-anchor" href="#계약-요약" aria-label="Permalink to &quot;계약 요약&quot;">​</a></h2><p>현재 증분은 <code>Foundation</code> 모듈 하나에 한정합니다. <code>Bootstrap.unity</code>가 App VContainer scope와 <strong>FSM</strong>을 소유하고, <code>Foundation.unity</code>는 명시적 child scope를 가진 화면이 됩니다. static <strong>Singleton</strong>과 service locator를 금지하며, 미래 <strong>Repository</strong>는 Unity-free inward contract로 둡니다. <strong>저장과 결정성</strong>, <strong>실패와 취소</strong>, 테스트 및 <strong>품질 게이트</strong>의 상세 규칙은 시스템 설계 계약을 따릅니다.</p><h2 id="구현-순서" tabindex="-1">구현 순서 <a class="header-anchor" href="#구현-순서" aria-label="Permalink to &quot;구현 순서&quot;">​</a></h2><table tabindex="0"><thead><tr><th>순서</th><th>작업</th><th>선행 조건</th><th>완료 증거</th></tr></thead><tbody><tr><td>1</td><td>Wiki 계약 고정</td><td>조사·설계 검증 PASS</td><td>Wiki 테스트 RED→GREEN 로그</td></tr><tr><td>2</td><td>루트 작업 계약 고정</td><td>Wiki GREEN</td><td><code>Concept.md</code>, <code>ToDo.md</code>, GitHub remote</td></tr><tr><td>3</td><td>FSM 테스트 작성</td><td>제품 코드 변경 전</td><td>올바른 missing type/behavior RED</td></tr><tr><td>4</td><td>VContainer와 최소 FSM 구현</td><td>FSM RED</td><td>EditMode GREEN</td></tr><tr><td>5</td><td>Bootstrap/Foundation 조립</td><td>FSM GREEN</td><td>compile, scope/build-order tests</td></tr><tr><td>6</td><td>정적 품질 게이트 구현</td><td>구조 파일 존재</td><td>mutation RED→cleanup→GREEN</td></tr><tr><td>7</td><td>실제 PlayMode QA</td><td>compile/tests GREEN</td><td>screenshot과 허용·거부 전환 기록</td></tr><tr><td>8</td><td>전체 검증</td><td>모든 증분 완료</td><td>Wiki, gate, Unity tests, 네 리뷰 PASS</td></tr></tbody></table><h2 id="단계-1-—-wiki-계약" tabindex="-1">단계 1 — Wiki 계약 <a class="header-anchor" href="#단계-1-—-wiki-계약" aria-label="Permalink to &quot;단계 1 — Wiki 계약&quot;">​</a></h2><h3 id="red" tabindex="-1">RED <a class="header-anchor" href="#red" aria-label="Permalink to &quot;RED&quot;">​</a></h3><p><code>node tools/wiki/test-build-wiki.mjs</code></p><p><code>Unity-System-Design.md</code>와 이 계획이 없거나 sidebar 연결과 필수 계약(FSM, VContainer, Singleton, Repository, 저장과 결정성, 실패와 취소, 품질 게이트)이 빠지면 실패해야 합니다.</p><h3 id="green" tabindex="-1">GREEN <a class="header-anchor" href="#green" aria-label="Permalink to &quot;GREEN&quot;">​</a></h3><p>두 문서를 만들고 <code>_Sidebar.md</code>와 <code>Home.md</code>에서 연결합니다. 빌드된 Wiki에서 링크와 필수 계약을 다시 읽습니다.</p><h2 id="단계-2-—-작업-범위-게이트" tabindex="-1">단계 2 — 작업 범위 게이트 <a class="header-anchor" href="#단계-2-—-작업-범위-게이트" aria-label="Permalink to &quot;단계 2 — 작업 범위 게이트&quot;">​</a></h2><p>제품 코드 변경 전에 루트 <code>Concept.md</code>와 <code>ToDo.md</code>를 만듭니다.</p><ul><li>Concept는 게임과 Unity 6000.7.0a5, VContainer 1.19.0, URP/Input System/Test Framework 기준을 설명합니다.</li><li>ToDo의 current module은 Foundation architecture 하나뿐입니다.</li><li>UI 화면 설계 변경이 아니므로 이 증분에서 새 <code>Design.md</code>는 만들지 않습니다.</li><li><code>git remote -v</code>에 GitHub remote가 있어야 합니다.</li></ul><h2 id="단계-3-—-fsm-red" tabindex="-1">단계 3 — FSM RED <a class="header-anchor" href="#단계-3-—-fsm-red" aria-label="Permalink to &quot;단계 3 — FSM RED&quot;">​</a></h2><p>EditMode 테스트를 제품 코드보다 먼저 작성합니다.</p><table tabindex="0"><thead><tr><th>사례</th><th>입력</th><th>PASS 조건</th></tr></thead><tbody><tr><td>happy</td><td><code>Booting + OpenFoundation</code></td><td><code>Transitioning</code>, load 1회</td></tr><tr><td>readiness</td><td>load 완료, ready 미완료</td><td><code>Foundation</code> commit 없음</td></tr><tr><td>success</td><td><code>SceneLoadSucceeded</code></td><td><code>Foundation</code>, receipt 존재</td></tr><tr><td>illegal</td><td>허용되지 않은 상태/trigger</td><td>typed rejection, 호출 0회</td></tr><tr><td>duplicate</td><td>전환 중 두 번째 요청</td><td>Busy, 추가 load 0회</td></tr><tr><td>failure</td><td>load 또는 scope 실패</td><td>staging dispose, Faulted</td></tr><tr><td>retry</td><td><code>Faulted + Retry</code></td><td>새 transition ID, 성공 가능</td></tr></tbody></table><p>RED는 missing type, missing member 또는 기대 동작 불일치여야 합니다. syntax error나 fixture 오류는 증거가 아닙니다.</p><h2 id="단계-4-—-최소-green" tabindex="-1">단계 4 — 최소 GREEN <a class="header-anchor" href="#단계-4-—-최소-green" aria-label="Permalink to &quot;단계 4 — 최소 GREEN&quot;">​</a></h2><h3 id="fsm" tabindex="-1">FSM <a class="header-anchor" href="#fsm" aria-label="Permalink to &quot;FSM&quot;">​</a></h3><ul><li><code>ApplicationFlowState</code></li><li><code>ApplicationFlowTrigger</code></li><li>typed <code>TransitionOutcome</code></li><li>pure transition table</li><li>single-flight coordinator</li><li>generation과 transition ID</li></ul><p>첫 GREEN은 실제 scene API 없이 fake scene loader로 얻습니다. 상태 commit은 ready signal 이후에만 합니다.</p><h3 id="vcontainer" tabindex="-1">VContainer <a class="header-anchor" href="#vcontainer" aria-label="Permalink to &quot;VContainer&quot;">​</a></h3><p>Makcha에서 실제 확인한 <code>jp.hadashikick.vcontainer</code> <code>#1.19.0</code>만 추가합니다. Addressables, Entities, LitMotion 등 호출자가 없는 패키지는 추가하지 않습니다.</p><ul><li><code>AppLifetimeScope</code>: FSM, scene catalog, scene loader 등록</li><li><code>FoundationLifetimeScope</code>: 화면 객체만 등록</li><li>parent enqueue를 사용한 명시적 child 구성</li><li>scope dispose와 cancellation의 소유권 테스트</li></ul><h2 id="단계-5-—-씬-조립" tabindex="-1">단계 5 — 씬 조립 <a class="header-anchor" href="#단계-5-—-씬-조립" aria-label="Permalink to &quot;단계 5 — 씬 조립&quot;">​</a></h2><p>Editor builder가 다음 결과를 반복 가능하게 만듭니다.</p><ol><li><code>Bootstrap.unity</code>: App scope와 bootstrap root만 포함</li><li><code>Foundation.unity</code>: 기존 orthographic camera와 light, Foundation scope 포함</li><li>Build Settings: Bootstrap 0, Foundation 1</li></ol><p>Bootstrap 외 <code>DontDestroyOnLoad</code>를 금지합니다. 화면과 gameplay object는 Foundation unload와 함께 제거됩니다.</p><h2 id="단계-6-—-repository·singleton-경계-품질-게이트" tabindex="-1">단계 6 — Repository·Singleton 경계 품질 게이트 <a class="header-anchor" href="#단계-6-—-repository·singleton-경계-품질-게이트" aria-label="Permalink to &quot;단계 6 — Repository·Singleton 경계 품질 게이트&quot;">​</a></h2><p>현재 증분에는 campaign Repository 구현을 만들지 않습니다. 대신 검사 가능한 경계를 고정합니다.</p><ul><li>Repository/Core 대상 경로에서 UnityEngine과 VContainer import 금지</li><li>runtime mutable static <code>Instance</code>, <code>Current</code>, collection 금지</li><li>service locator와 runtime object search 금지</li><li>scene load API는 adapter allowlist만 허용</li><li><code>DontDestroyOnLoad</code>는 Bootstrap allowlist만 허용</li></ul><p>mutation proof:</p><ol><li>임시 runtime 파일에 금지된 <code>DontDestroyOnLoad</code> 또는 <code>Current</code>를 추가합니다.</li><li><code>node tools/architecture/check-unity-architecture.mjs</code>가 규칙 이름과 파일을 출력하며 nonzero로 끝나야 합니다.</li><li>임시 파일을 제거합니다.</li><li>같은 명령이 exit 0이어야 합니다.</li><li>temp 파일과 프로세스가 남지 않았음을 cleanup receipt에 기록합니다.</li></ol><h2 id="단계-7-—-저장과-결정성·실패와-취소-계약-보존" tabindex="-1">단계 7 — 저장과 결정성·실패와 취소 계약 보존 <a class="header-anchor" href="#단계-7-—-저장과-결정성·실패와-취소-계약-보존" aria-label="Permalink to &quot;단계 7 — 저장과 결정성·실패와 취소 계약 보존&quot;">​</a></h2><p>Foundation 구현은 아직 저장하지 않지만 향후 경계를 침범하지 않아야 합니다.</p><ul><li>scene timing, frame count와 wall clock을 FSM 결과에 사용하지 않음</li><li>모든 transition 요청에 안정 ID와 typed result 사용</li><li>cancellation을 failure와 구분</li><li>late callback은 generation 검사</li><li>child scope dispose가 token을 먼저 취소</li><li>fire-and-forget과 fixed sleep/polling 금지</li></ul><p>미래 Repository와 save adapter는 temp→검증→backup→원자 교체와 목적별 RNG stream 규칙을 따라야 합니다.</p><h2 id="단계-8-—-unity-검증" tabindex="-1">단계 8 — Unity 검증 <a class="header-anchor" href="#단계-8-—-unity-검증" aria-label="Permalink to &quot;단계 8 — Unity 검증&quot;">​</a></h2><p>파일 변경 후 실제 Unity Editor에서 다음을 실행합니다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>unity run Game --editor-version 6000.7.0a5 -- -nographics -executeMethod Janseon.Foundation.Editor.FoundationProjectBuilder.BuildFoundationScene -logFile -</span></span>
<span class="line"><span>unity test Game --editor-version 6000.7.0a5 --mode EditMode --report-format junit --output .omo/evidence/unity/editmode.xml --timeout 600</span></span>
<span class="line"><span>unity test Game --editor-version 6000.7.0a5 --mode PlayMode --report-format junit --output .omo/evidence/unity/playmode.xml --timeout 600</span></span></code></pre></div><p>Play Mode에서 Bootstrap이 Foundation을 열고 App/child scope가 각각 하나인지 확인합니다. public flow API로 이미 Foundation인 상태의 요청이나 불법 trigger를 보내 typed rejection과 추가 load 0회를 관찰합니다.</p><h2 id="시각-검증" tabindex="-1">시각 검증 <a class="header-anchor" href="#시각-검증" aria-label="Permalink to &quot;시각 검증&quot;">​</a></h2><p>실제 Unity Play Mode를 <code>-batchmode</code>로 실행하고 고정 카메라의 RenderTexture 또는 ScreenCapture 결과를 PNG와 JSON receipt로 기록합니다. 다음 네 축을 독립 검토하며 하나라도 명시적 PASS가 아니면 완료가 아닙니다.</p><ul><li>COMPOSITION</li><li>SPRITE_FIDELITY</li><li>TYPOGRAPHY</li><li>PRODUCT_POLISH</li></ul><p>batchmode PlayMode 캡처나 receipt가 없으면 정적 검증으로 대체하지 않고 미검증으로 기록합니다. 대화형 Editor와 uLoop는 사용하지 않습니다.</p><h2 id="최종-품질-게이트" tabindex="-1">최종 품질 게이트 <a class="header-anchor" href="#최종-품질-게이트" aria-label="Permalink to &quot;최종 품질 게이트&quot;">​</a></h2><p>다음을 한 번씩 clean 상태에서 실행합니다.</p><ol><li><code>node tools/wiki/test-build-wiki.mjs</code></li><li><code>node tools/architecture/check-unity-architecture.mjs</code></li><li>Unity compile</li><li>EditMode tests</li><li>PlayMode tests</li><li>실제 Play Mode 허용·거부 시나리오</li><li>네 시각 리뷰</li></ol><p>모든 임시 mutation, Unity process, capture context와 temp file을 정리한 뒤에만 완료합니다.</p><h2 id="완료-조건" tabindex="-1">완료 조건 <a class="header-anchor" href="#완료-조건" aria-label="Permalink to &quot;완료 조건&quot;">​</a></h2><ul><li>FSM이 유일한 scene transition 권한입니다.</li><li>VContainer App/child scope 관계와 dispose가 검증됩니다.</li><li>static Singleton/service locator가 품질 게이트에서 실패합니다.</li><li>Repository 경계는 Unity-free 계약으로 보호됩니다.</li><li>저장과 결정성, 실패와 취소 규칙을 깨는 코드가 없습니다.</li><li>Wiki, architecture gate, compile, EditMode, PlayMode와 실제 화면 검증이 모두 PASS합니다.</li></ul>`,53)])])}const m=e(d,[["render",n]]);export{h as __pageData,m as default};
